mapper.select:
SELECT id, file_name, file_url, file_size, content_type, bucket_name, object_name, status, created_at, updated_at
FROM file_metadata
WHERE id = #{id}

SELECT f.id, f.file_name, f.file_size, f.content_type, f.status, f.created_at, f.updated_at, (SELECT count(*) FROM text_chunk c WHERE c.file_id = f.id) AS chunk_count FROM file_metadata f
AND f.file_name ILIKE '%' || #{keyword} || '%'
AND f.status = #{status}
ORDER BY f.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT count(*) FROM file_metadata f
AND f.file_name ILIKE '%' || #{keyword} || '%'
AND f.status = #{status}

mapper.update:
UPDATE file_metadata
SET status = #{status}, updated_at = now()
WHERE id = #{id}
